var t=`1271-tembleque`;var n=`world-1271`;var a=`PR`;var r=`central-america-caribbean`;var o=8;var s=189;var l={en:`Tembleque`,ua:`Темблеке`};var c={en:`Tembleque is a dish from Puerto Rico featuring coconut milk, cornstarch, toasted coconut flakes. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Темблеке, страва кухні країни Пуерто-Рико з такими основними складниками: кокосове молоко, кукурудзяний крохмаль, підсмажені кокосові пластівці. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`coconut-milk`,800,`ml`],[`cornstarch`,110,`g`],[`white-granulated-sugar`,140,`g`],[`table-salt`,3,`g`]]},{en:`Dissolve or bloom the setting ingredients as directed, combine with the base and refrigerate for about 16 minutes until fully set.`,ua:`Підготуйте желювальні складники за інструкцією, змішайте з основою та охолоджуйте приблизно 16 хвилин до повного застигання.`,t:[`gelatin-setting`,`rapid-chilling`],m:16,i:[]},{en:`Refrigerate the prepared mixture for about 160 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 160 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:160,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`ground-cinnamon`,5,`g`],[`toasted-coconut-flakes`,70,`g`]]}];var g={slug:t,id:n,country:`PR`,region:r,servings:8,minutes:189,title:l,text:c,steps:d};export{a as country,g as default,n as id,s as minutes,r as region,o as servings,t as slug,d as steps,c as text,l as title};